//! Acceptance test skeletons for SPEC-KAPU.md v1.0 (TERV.md M1).
//!
//! One test per Acceptance point of the specification plus one per error code
//! (FR-20) and per reader edge case (FR-15). Tests that need an implementation
//! are `#[ignore]`d with the milestone that delivers them; running them with
//! `cargo test -- --ignored` makes every one of them fail on purpose until then.
//! The tests that only check the vector files themselves run today.
//!
//! Test vectors live in `tests/vectors/` at the repository root and are
//! generated by `tools/build_vectors.py`; `expected.json` records what each
//! file must produce.
#![allow(
    clippy::panic,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing
)]

use std::path::PathBuf;

fn vectors_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/vectors")
}

fn vector(name: &str) -> Vec<u8> {
    let path = vectors_dir().join(name);
    std::fs::read(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

fn expected() -> serde_json::Value {
    let text = std::fs::read_to_string(vectors_dir().join("expected.json")).expect("expected.json");
    serde_json::from_str(&text).expect("expected.json is valid JSON")
}

/// Marks a test as waiting for a later milestone. It always fails when run.
fn pending(milestone: &str, what: &str) -> ! {
    panic!("not implemented until {milestone}: {what}")
}

// ---------------------------------------------------------------------------
// Vector integrity: these run now.
// ---------------------------------------------------------------------------

#[test]
fn expected_json_lists_every_vector_file_and_nothing_else() {
    let exp = expected();
    let listed = exp.as_object().expect("object");
    let mut on_disk: Vec<String> = std::fs::read_dir(vectors_dir())
        .expect("vectors dir")
        .map(|e| e.expect("entry").file_name().to_string_lossy().into_owned())
        .filter(|n| {
            std::path::Path::new(n)
                .extension()
                .is_some_and(|e| e.eq_ignore_ascii_case("kapu"))
        })
        .collect();
    on_disk.sort();
    let mut keys: Vec<String> = listed.keys().cloned().collect();
    keys.sort();
    assert_eq!(
        keys, on_disk,
        "expected.json and tests/vectors/*.kapu differ"
    );
    assert_eq!(listed.len(), 14, "1 sample + 11 error codes + 2 edge cases");
}

#[test]
fn sample_header_is_512_bytes_and_ends_with_lf() {
    let data = vector("minta.kapu");
    assert!(data.len() > kapu_core::HEADER_LEN);
    assert_eq!(data[kapu_core::HEADER_LEN - 1], b'\n');
    let first_line = format!("%KAPU {}\n", kapu_core::FORMAT_VERSION);
    assert!(data.starts_with(first_line.as_bytes()));
}

#[test]
fn sample_sections_appear_in_spec_order() {
    let data = vector("minta.kapu");
    let text = String::from_utf8_lossy(&data);
    let mut last = 0;
    for marker in [
        "\n#MAP\n",
        "\n#DESC\n",
        "\n#GRAPH\n",
        "\n#INDEX\n",
        "\n#DOCS\n",
        "\n#BODY\n",
    ] {
        let pos = text[last..]
            .find(marker)
            .unwrap_or_else(|| panic!("{marker:?} missing"));
        last += pos + marker.len();
    }
}

#[test]
fn sample_contains_no_cr() {
    assert!(!vector("minta.kapu").contains(&b'\r'));
}

#[test]
fn every_invalid_vector_differs_from_the_sample() {
    let sample = vector("minta.kapu");
    for (name, entry) in expected().as_object().expect("object") {
        if name == "minta.kapu" {
            continue;
        }
        let code = entry["expect"].as_str().expect("expect");
        assert!(
            code.starts_with('E') || code == "stale",
            "{name}: unexpected code {code}"
        );
        assert_ne!(vector(name), sample, "{name} is identical to the sample");
    }
}

