#[test]
fn sample_validates_clean() {
    use kapu_core::{Level, validate};
    let data = vector("minta.kapu");
    let basic = validate(&data, Level::Basic).unwrap();
    assert_eq!((basic.rooms, basic.doors, basic.full), (3, 7, false));
    assert!(validate(&data, Level::Full).unwrap().full);
}

#[test]
fn full_validation_reports_the_expected_code_for_every_vector() {
    use kapu_core::{Level, validate};
    for (name, entry) in expected().as_object().unwrap() {
        let want = match entry["expect"].as_str().unwrap() {
            "ok" => None,
            // an in-place edit keeps the layout; the full check starts with bodyhash, which changed too
            "stale" if name.contains("same-length") => Some("E006"),
            // a grown room breaks the declared body length
            "stale" => Some("E005"),
            code => Some(code),
        };
        let got = validate(&vector(name), Level::Full)
            .err()
            .map(|e| e.code.as_str());
        assert_eq!(got, want, "{name}");
    }
}

#[test]
fn header_of_sample_matches_expected_json() {
    let h = kapu_core::Header::parse(&vector("minta.kapu")).unwrap();
    let want = expected()["minta.kapu"]["header_body"]
        .as_str()
        .unwrap()
        .to_owned();
    assert_eq!(format!("{}+{}", h.body.start, h.body.len), want);
    assert_eq!((h.rooms, h.doors, h.groups), (3, 7, 2));
    assert_eq!(h.emb, "none");
}

#[test]
fn sections_parse_in_every_vector_whose_fault_is_elsewhere() {
    use kapu_core::{BodyLength, Limits, Sections};
    for (name, entry) in expected().as_object().unwrap() {
        let code = entry["expect"].as_str().unwrap();
        let data = vector(name);
        let strict = Sections::parse(&data);
        match code {
            "E001" | "E002" | "E003" | "E004" | "E005" | "E011" => {
                assert_eq!(strict.unwrap_err().code.as_str(), code, "{name}");
            }
            "stale" => {
                // a grown body fails the strict length check but the reader tolerates it
                let tolerant =
                    Sections::parse_with(&data, &Limits::default(), BodyLength::Tolerate);
                assert!(tolerant.is_ok(), "{name}: {:?}", tolerant.err());
            }
            _ => assert!(strict.is_ok(), "{name}: {:?}", strict.err()),
        }
    }
}

